def DD(q, kind, k=1):
    if kind == 'odd3':
        h = q ** 3
    if kind == 'abs2':
        h = q * abs(q)
    if kind == 'rat':
        h = q * abs(q) / (1 + k * abs(q))
    if kind == 'rat2':
        h = q ** 3 / (1 + k * q * q)
    if kind == 'tanh':
        h = np.tanh(k * q)
    if kind == 'sin':
        h = np.sin(k * q)
    if kind == 'asinh':
        h = np.arcsinh(k * q)
    if kind == 'cube2':
        return np.c_[np.ones(len(q)), q, q * q, q ** 3]
    if kind == 'cube4':
        return np.c_[np.ones(len(q)), q, q * q, q ** 3, q ** 4]
    return np.c_[np.ones(len(q)), q, h]
